"""The schedule a retrying client would follow. See task.md."""

from __future__ import annotations

import math
from fractions import Fraction

RETRYABLE = frozenset({429, 500, 502, 503})

# A recorded response: {"status": int, "retry_after_ms": int}  (the second key
# is optional).
Response = dict

# A planned attempt: {"number": int, "start_ms": int, "delay_ms": int}.
Attempt = dict


class PolicyError(ValueError):
    """Raised for a policy or deadline that cannot describe a schedule."""


def _factor(raw) -> Fraction:
    if isinstance(raw, list):
        num, den = raw
        if den <= 0 or num < den:
            raise PolicyError(f"factor {raw} must be a ratio of at least 1")
        return Fraction(num, den)
    if raw < 1:
        raise PolicyError(f"factor {raw} must be at least 1")
    return Fraction(raw)


def plan(policy: dict, responses: list[Response], deadline_ms: int) -> list[Attempt]:
    """Return the attempts a client under `policy` would make against `responses`."""
    base_ms = policy["base_ms"]
    max_delay_ms = policy["max_delay_ms"]
    max_attempts = policy["max_attempts"]
    if base_ms <= 0:
        raise PolicyError(f"base_ms {base_ms} must be positive")
    factor = _factor(policy["factor"])
    if max_attempts < 1:
        raise PolicyError(f"max_attempts {max_attempts} must be at least 1")
    if deadline_ms < 0:
        raise PolicyError(f"deadline_ms {deadline_ms} must not be negative")

    attempts: list[Attempt] = []
    start_ms = 0
    delay_ms = 0
    n = 1
    while n <= max_attempts and n <= len(responses) and start_ms < deadline_ms:
        attempts.append({"number": n, "start_ms": start_ms, "delay_ms": delay_ms})
        response = responses[n - 1]
        if response["status"] not in RETRYABLE:
            break
        n += 1
        if "retry_after_ms" in response:
            delay_ms = response["retry_after_ms"]
        else:
            backed = math.floor(base_ms * factor ** (n - 2))
            delay_ms = min(backed, max_delay_ms)
        start_ms += delay_ms
    return attempts
